  [' (this engine has no temperature simulation - no effect)'] = ' (dieser Motor hat keine Temperatursimulation - keine Wirkung)',
  ['Radiator: only its model is shown (no physics). For cooling, pick it in the ">> RADIATOR (cooling, logic)" folder.'] = 'Kühler: nur sein Modell wird gezeigt (ohne Physik). Für die Kühlung wähle ihn im Ordner ">> KÜHLER (Kühlung, Logik)".',
  ['Part %s has no mesh points of its own (its model hangs on its own car\'s body) - only its model will appear, without physics.'] = 'Teil %s hat keine eigenen Netzpunkte (sein Modell hängt an der Karosserie seines Autos) - nur sein Modell erscheint, ohne Physik.',
  ['This part has no model (data only) - nothing to show.'] = 'Dieses Teil hat kein Modell (nur Daten) - nichts zu zeigen.',
  ['%s is already installed.'] = '%s ist bereits installiert.',
  ['%s found nothing to hold on to (too far from the frame and body of the vehicle) - it will fall. Move it closer or raise "Max gap".'] = '%s hat nichts zum Festhalten gefunden (zu weit von Rahmen und Karosserie des Fahrzeugs) - es fällt herunter. Schiebe es näher oder erhöhe "Max. Abstand".',
  ['%s is a hitch (%s): it only works with physics - press "With physics" in section 2.'] = '%s ist eine Anhängerkupplung (%s): sie funktioniert nur mit Physik - drücke "Mit Physik" in Abschnitt 2.',
  ['%s: installed right away (data only, no model - nothing to place).'] = '%s: sofort installiert (nur Daten, kein Modell - nichts zu platzieren).',
  ['%s has nothing to fill: it needs "%s" (e.g. the air tank of the same vehicle) - add that too.'] = '%s hat nichts zu füllen: es braucht "%s" (z. B. den Lufttank desselben Fahrzeugs) - füge das auch hinzu.',
  ['Suspension settings applied (logic).'] = 'Fahrwerkseinstellungen angewendet (Logik).',
  ['Suspension restored to original.'] = 'Fahrwerk auf Original zurückgesetzt.',
  ['Could not read the springs / dampers of this suspension.'] = 'Federn / Dämpfer dieses Fahrwerks konnten nicht gelesen werden.',
  ['%s character: springs %s N/m, damping %s, sway bar %s'] = 'Charakter %s: Federn %s N/m, Dämpfung %s, Stabilisator %s',
  ['Adds electronics to any vehicle (what the vehicle already has stays as it is).'] = 'Fügt jedem Fahrzeug Elektronik hinzu (was das Fahrzeug schon hat, bleibt wie es ist).',
  ['State: installed - %s'] = 'Status: installiert - %s',
  ['State: not installed'] = 'Status: nicht installiert',
  ['ABS (the brakes never lock up)'] = 'ABS (die Bremsen blockieren nie)',
  ['Traction control (TC) - no wheelspin'] = 'Traktionskontrolle (TC) - kein Durchdrehen',
  ['Stability control (ESC) - no sliding / spinning out'] = 'Stabilitätskontrolle (ESC) - kein Rutschen / Ausbrechen',
  ['Generic settings, not tuned for this vehicle: on very unusual vehicles it may be imprecise.'] = 'Allgemeine Einstellungen, nicht auf dieses Fahrzeug abgestimmt: bei sehr ungewöhnlichen Fahrzeugen evtl. ungenau.',
  ['Line lock (holds the front brakes - burnout)'] = 'Line Lock (hält die Vorderbremsen - Burnout)',
  ['INSTALL / UPDATE'] = 'INSTALLIEREN / AKTUALISIEREN',
  ['Nothing selected.'] = 'Nichts ausgewählt.',
  ['Safety electronics installed. Modes: radial menu (Vehicle features) or Options > Controls.'] = 'Sicherheitselektronik installiert. Modi: Radialmenü (Fahrzeugfunktionen) oder Optionen > Steuerung.',
  ['While driving: TC / ESC modes (ESC + TC / TC / Off) - key "Toggle ESC mode" or the radial menu.'] = 'Während der Fahrt: TC / ESC-Modi (ESC + TC / TC / Aus) - Taste "ESC-Modus umschalten" oder das Radialmenü.',
  ['2-step: standing still, hold the brake + full throttle, let go of the brake - launch. Switch it on in the menu / "Toggle Two-Step".'] = '2-Step: im Stand Bremse halten + Vollgas, Bremse loslassen - Start. Einschalten im Menü / "Two-Step umschalten".',
  ['Line lock: hold the brake, press "Toggle Line Lock" - the front wheels are held, the rear ones spin.'] = 'Line Lock: Bremse halten, "Line Lock umschalten" drücken - die Vorderräder werden gehalten, die Hinterräder drehen durch.',
  ['Cut'] = 'Schnitt',
