  ['Pick at least one front end part.'] = 'Wähle mindestens ein Frontteil.',
  ['Front end of %s: %d parts. Move it and set its size in the Part tab, then press ATTACH.'] = 'Front von %s: %d Teile. Verschiebe sie und stelle ihre Größe im Teil-Tab ein, dann drücke ANBRINGEN.',
  ['Front end of %s installed (%d parts, %d of your own taken off).'] = 'Front von %s installiert (%d Teile, %d eigene abgenommen).',
  ['%d. FRONT END of %s (%d parts)'] = '%d. FRONT von %s (%d Teile)',
  ['The front end comes off, your vehicle\'s own front parts come back.'] = 'Die Front kommt ab, die eigenen Frontteile deines Fahrzeugs kommen zurück.',
  ['A real suspension swap: the donor suspension with its wheels, hubs, brakes and steering goes onto your vehicle.'] = 'Echter Fahrwerkstausch: das Fahrwerk des Spenders mit Rädern, Naben, Bremsen und Lenkung kommt an dein Fahrzeug.',
  ['Or - only the character, your suspension geometry stays (safer):'] = 'Oder - nur der Charakter, deine Fahrwerksgeometrie bleibt (sicherer):',
  ['LOGIC: take over only the character - %s'] = 'LOGIK: nur den Charakter übernehmen - %s',
  ['UI size'] = 'UI-Größe',
  ['The size of the window\'s text and buttons (applied when you let go of the slider).'] = 'Größe von Text und Knöpfen des Fensters (wird beim Loslassen des Reglers übernommen).',
  ['Pick at least one body part.'] = 'Wähle mindestens ein Karosserieteil.',
