  ['Cancel'] = 'Abbrechen',
  ['The vehicle went unstable after the change - it was undone, the vehicle is back as it was.'] = 'Das Fahrzeug wurde nach der Änderung instabil - sie wurde rückgängig gemacht, das Fahrzeug ist wieder wie vorher.',
  ['Part picture on mouse hover'] = 'Teilbild beim Überfahren mit der Maus',
  ['Rest the mouse on a part in the list to see its saved picture in a small window. New pictures are only taken with "Take part pictures" ticked.'] = 'Halte die Maus auf einem Teil in der Liste, um sein gespeichertes Bild in einem kleinen Fenster zu sehen. Neue Bilder entstehen nur, wenn "Teilebilder aufnehmen" angehakt ist.',
  ['Delete pictures'] = 'Bilder löschen',
  ['Deletes the saved part pictures - they are taken again next time.'] = 'Löscht die gespeicherten Teilbilder - sie werden beim nächsten Mal neu erstellt.',
  ['Multiplayer: only pictures saved before are shown.'] = 'Multiplayer: nur bereits gespeicherte Bilder werden gezeigt.',
  ['Loading the picture...'] = 'Bild lädt...',
  ['No picture for this part.'] = 'Kein Bild für dieses Teil.',
  ['The saved part pictures were deleted.'] = 'Die gespeicherten Teilbilder wurden gelöscht.',
