  ['Stop'] = 'Stopp',
  ['Take part pictures'] = 'Teilebilder aufnehmen',
  ['No new parts left in this vehicle\'s configs - the others get their picture on mouse hover.'] = 'Keine neuen Teile mehr in den Konfigurationen dieses Fahrzeugs - die anderen bekommen ihr Bild beim Überfahren mit der Maus.',
  ['Off: nothing gets photographed (no stutter), only pictures taken before show. Ticked: a few factory configs of the picked vehicle load and all their parts get photographed (it stutters), and a part without a picture is photographed when the mouse rests on it.'] = 'Aus: es wird nichts fotografiert (kein Ruckeln), nur schon gemachte Bilder werden gezeigt. Angehakt: einige Werkskonfigurationen des gewählten Fahrzeugs werden geladen und alle ihre Teile fotografiert (es ruckelt), und ein Teil ohne Bild wird fotografiert, wenn die Maus darauf ruht.',
  ['%s  [data only]'] = '%s  [nur Daten]',
  ['No model - adds to the vehicle: %s'] = 'Kein Modell - fügt dem Fahrzeug hinzu: %s',
  ['(%d hidden: no model, no effect)'] = '(%d ohne Modell und Wirkung ausgeblendet)',
  ['Bulbs, ECU tunes and other parts without points, a model or devices of their own - they do nothing on another vehicle, so they are not shown.'] = 'Glühbirnen, ECU-Abstimmungen und andere Teile ohne eigene Punkte, Modell oder Geräte - an einem anderen Fahrzeug bewirken sie nichts, darum werden sie nicht gezeigt.',
  ['air compressor'] = 'Luftkompressor',
  ['air tank'] = 'Lufttank',
  ['fuel tank'] = 'Kraftstofftank',
  ['battery'] = 'Batterie',
  ['nitrous (N2O) bottle'] = 'Lachgasflasche (N2O)',
  ['electric motor'] = 'Elektromotor',
  ['By speed: slow - the opposite way, fast - the same way'] = 'Nach Tempo: langsam - gegenläufig, schnell - gleichläufig',
  ['Like the Pessima AWS: by the steering angle'] = 'Wie der Pessima AWS: nach dem Lenkwinkel',
  ['Always the opposite way (a small turning circle)'] = 'Immer gegenläufig (kleiner Wendekreis)',
  ['Always the same way (crab walk)'] = 'Immer gleichläufig (Hundegang)',
  ['Rear wheel steering (4WS, like the Pessima AWS)'] = 'Hinterradlenkung (4WS, wie beim Pessima AWS)',
  ['The rear wheels steer with the front ones: each wheel with its disc gets a kingpin of its own, the suspension or axle stays in place.'] = 'Die Hinterräder lenken mit den Vorderrädern: jedes Rad mit seiner Bremsscheibe bekommt einen eigenen Achsschenkelbolzen, Aufhängung oder Achse bleiben, wo sie sind.',
  ['Largest angle'] = 'Größter Winkel',
  ['TURN ON / UPDATE'] = 'EINSCHALTEN / AKTUALISIEREN',
  ['Rear wheel steering is on. If the vehicle goes unstable, the change is undone by itself.'] = 'Hinterradlenkung ist an. Wird das Fahrzeug instabil, wird die Änderung von selbst zurückgenommen.',
  ['Turn off'] = 'Ausschalten',
  ['The rear wheel hubs could not be separated - this suspension can not steer.'] = 'Die Radnaben hinten ließen sich nicht abtrennen - diese Aufhängung kann nicht lenken.',
  ['State: on - %d rear wheels steer, up to %d deg.'] = 'Zustand: an - %d Hinterräder lenken, bis %d Grad.',
  ['The angle standing and slow. The "by speed" mode holds it to a few degrees at speed. Above ~20 deg the wheels may touch the body or the arms, and the suspension may bend.'] = 'Der Winkel im Stand und langsam. Der Modus "nach Tempo" begrenzt ihn bei Fahrt auf wenige Grad. Über ~20 Grad können die Räder Karosserie oder Lenker berühren und die Aufhängung sich verbiegen.',
  ['A different wheel on every corner'] = 'Ein anderes Rad an jeder Ecke',
  ['When on, the game\'s Parts menu (ESC > Vehicle Config) gets "- left" and "- right" next to "Front Wheels" and "Rear Wheels": every wheel gets its own rim and tyre.'] = 'Eingeschaltet bekommt das Parts-Menü des Spiels (ESC > Vehicle Config) bei "Front Wheels" und "Rear Wheels" ein "- left" und ein "- right": jedes Rad bekommt seine eigene Felge und seinen eigenen Reifen.',
  ['State: on.'] = 'Zustand: an.',
  ['TURN ON'] = 'EINSCHALTEN',
  ['Corner wheels are on: ESC > Vehicle Config > Parts - pick a wheel for every corner.'] = 'Eckräder sind an: ESC > Vehicle Config > Parts - wähle für jede Ecke ein Rad.',
  ['EV swap (electric motor)'] = 'EV-Swap (Elektromotor)',
  ['The combustion engine becomes an electric motor; the clutch / gearbox stay. The fuel tanks become a battery.'] = 'Der Verbrennungsmotor wird zum Elektromotor; Kupplung / Getriebe bleiben. Die Kraftstofftanks werden zur Batterie.',
  ['Power (kW)'] = 'Leistung (kW)',
  ['Battery (kWh)'] = 'Batterie (kWh)',
  ['MAKE IT ELECTRIC'] = 'ELEKTRISCH MACHEN',
  ['EV swap: %d kW, battery %d kWh.'] = 'EV-Swap: %d kW, Batterie %d kWh.',
  ['Bring the combustion engine back'] = 'Verbrennungsmotor zurück',
  ['State: electric - %d kW, %.0f Nm, up to %d rpm, battery %d kWh.'] = 'Zustand: elektrisch - %d kW, %.0f Nm, bis %d U/min, Batterie %d kWh.',
  ['Rocket (JATO)'] = 'Rakete (JATO)',
  ['The pickup\'s JATO rocket on your vehicle: place it, size it (bigger is stronger) and attach it. Fire: hold Alt+J, or "JATO" in the Powertrain menu.'] = 'Die JATO-Rakete des Pickups an deinem Fahrzeug: platzieren, Größe einstellen (größer ist stärker) und anbringen. Zünden: Alt+J halten oder "JATO" im Powertrain-Menü.',
  ['Lowrider hydraulics'] = 'Lowrider-Hydraulik',
  ['A hydraulic cylinder at every wheel: the front, rear, sides and the whole vehicle go up / down with keys, and it can hop.'] = 'An jedem Rad ein Hydraulikzylinder: Front, Heck, Seiten und das ganze Fahrzeug gehen per Taste hoch / runter, und es kann springen.',
  ['Travel (cm)'] = 'Hub (cm)',
  ['Speed'] = 'Geschwindigkeit',
  ['Stiffness (kN/m)'] = 'Steifigkeit (kN/m)',
  ['Hydraulics are on.'] = 'Hydraulik ist an.',
  ['Reset the height'] = 'Höhe zurücksetzen',
  ['State: on - %d cylinders.'] = 'Zustand: an - %d Zylinder.',
  ['Keys: Alt + Numpad 8/2 front, 9/3 rear, 4/6 lean, 5/0 the whole vehicle, Alt + Space hop (rebind in Options > Controls).'] = 'Tasten: Alt + Numpad 8/2 Front, 9/3 Heck, 4/6 neigen, 5/0 ganzes Fahrzeug, Alt + Leertaste springen (änderbar in Options > Controls).',
  ['Maybach dance (5 s)'] = 'Maybach-Tanz (5 s)',
  ['Maybach dance: Alt + Numpad 7 - the vehicle bounces for 5 s (press again to stop).'] = 'Maybach-Tanz: Alt + Numpad 7 - das Fahrzeug hüpft 5 s lang (erneut drücken zum Stoppen).',
  ['Jet car (rocket on W)'] = 'Düsenauto (Rakete auf W)',
  ['The attached rocket (JATO) runs on W like the 1950s jet cars: the harder you press the throttle, the harder it pushes (not in reverse). Alt+J still works.'] = 'Die angebaute Rakete (JATO) läuft auf W wie die Düsenautos der 1950er: je stärker du Gas gibst, desto stärker schiebt sie (nicht im Rückwärtsgang). Alt+J funktioniert weiter.',
  ['Fuel (s at full thrust)'] = 'Treibstoff (s bei voller Schubkraft)',
  ['Jet car: the rocket runs on W.'] = 'Düsenauto: die Rakete läuft auf W.',
  ['State: on - the rocket runs on W, %d s of fuel (R refills it).'] = 'Zustand: an - die Rakete läuft auf W, %d s Treibstoff (R füllt nach).',
  ['There is no rocket on the vehicle: attach one in section 1 with the "Rocket (JATO)" button, then press TURN ON / UPDATE.'] = 'Am Fahrzeug ist keine Rakete: baue sie in Teil 1 mit dem Knopf "Rakete (JATO)" an und drücke dann EINSCHALTEN / AKTUALISIEREN.',
  ['  [no logic]'] = '  [ohne Logik]',
