  ['Tilt forward / back (deg)'] = 'Neigung vor / zurück (Grad)',
  ['Lean to the side (deg)'] = 'Schräglage zur Seite (Grad)',
  ['>> FRONT SUBFRAME SWAP'] = '>> VORDEREN HILFSRAHMEN TAUSCHEN',
  ['>> REAR SUBFRAME SWAP'] = '>> HINTEREN HILFSRAHMEN TAUSCHEN',
  ['Front subframe'] = 'Vorderer Hilfsrahmen',
  ['Rear subframe'] = 'Hinterer Hilfsrahmen',
  ['FRONT SUBFRAME'] = 'VORDERER HILFSRAHMEN',
  ['REAR SUBFRAME'] = 'HINTERER HILFSRAHMEN',
  ['The vehicle has no subframe or suspension on that side: put its own subframe back (Parts menu) and try again.'] = 'Das Fahrzeug hat auf dieser Seite weder Hilfsrahmen noch Fahrwerk: setze seinen eigenen Hilfsrahmen wieder ein (Parts-Menü) und versuche es erneut.',
  ['The whole donor subframe with everything on it (suspension, hubs, wheels) in place of your subframe. The donor engine (of a mid-engined car) stays out - your own engine drives the new wheels through the universal drivetrain. A suspension from another vehicle can still be swapped into it afterwards.'] = 'Der ganze Hilfsrahmen des Spenders mit allem, was daran ist (Fahrwerk, Naben, Räder), anstelle deines Hilfsrahmens. Der Motor des Spenders (eines Mittelmotorautos) bleibt weg - dein eigener Motor treibt die neuen Räder über den universellen Antriebsstrang an. Danach lässt sich noch das Fahrwerk eines anderen Fahrzeugs hineintauschen.',
  ['The donor subframe\'s engine stays out - your own engine drives the new wheels through the universal drivetrain (%s).'] = 'Der Motor des Spender-Hilfsrahmens bleibt weg - dein eigener Motor treibt die neuen Räder über den universellen Antriebsstrang an (%s).',
  ['Comes with (%d of %d)'] = 'Kommt mit (%d von %d)',
  ['Untick what you don\'t need: that part and everything below it stays out of the preview and the vehicle.'] = 'Entferne den Haken bei allem, was du nicht brauchst: dieses Teil und alles darunter bleibt aus der Vorschau und aus dem Fahrzeug weg.',
  ['None'] = 'Keine',
  ['Only the part itself, without its sub parts (e.g. a frame without its body, engine and suspension).'] = 'Nur das Teil selbst, ohne seine Unterteile (z. B. ein Rahmen ohne Karosserie, Motor und Fahrwerk).',
  ['(engine - no logic)'] = '(Motor - ohne Logik)',
  ['A ticked donor engine comes as a part only (model and weight, it does not run) - your own engine still drives the vehicle.'] = 'Ein angehakter Spendermotor kommt nur als Teil (Modell und Gewicht, er läuft nicht) - dein eigener Motor treibt das Fahrzeug weiter an.',
  ['Update the preview'] = 'Vorschau aktualisieren',
  ['No picture yet - tick "Take part pictures" below the list.'] = 'Noch kein Bild - hake "Teilebilder aufnehmen" unter der Liste an.',
  ['Cut this part (cuts: %d)'] = 'Dieses Teil schneiden (Schnitte: %d)',
  ['Cut part of the preview off (e.g. keep only the front of a frame), then move it and ATTACH - only what is left comes onto the vehicle.'] = 'Schneide einen Teil der Vorschau ab (z. B. nur die Front eines Rahmens behalten), dann verschiebe sie und BEFESTIGE sie - nur der Rest kommt ans Fahrzeug.',
  ['Could not read the part.'] = 'Das Teil konnte nicht gelesen werden.',
  ['Part length: %.2f m'] = 'Länge des Teils: %.2f m',
  ['CUT THE PART'] = 'TEIL SCHNEIDEN',
  ['The part is cut - move it and ATTACH.'] = 'Das Teil ist geschnitten - verschieben und BEFESTIGEN.',
  ['Whole part again'] = 'Ganzes Teil zurück',
  ['There is nothing of the part to cut there.'] = 'An dieser Stelle gibt es vom Teil nichts zu schneiden.',
  ['Steering lock (front wheel angle)'] = 'Lenkeinschlag (Winkel der Vorderräder)',
  ['Change the steering lock'] = 'Lenkeinschlag ändern',
  ['Virtual steering: each front hub gets a kingpin of its own and the steering turns it exactly up to this angle; the vehicle\'s own steering cylinders only hold the wheels straight.'] = 'Virtuelle Lenkung: jede vordere Nabe bekommt einen eigenen Achsschenkelbolzen, und die Lenkung dreht sie genau bis zu diesem Winkel; die eigenen Lenkzylinder des Fahrzeugs halten die Räder nur gerade.',
  ['(the vehicle\'s own: ~%.0f deg)'] = '(eigener des Fahrzeugs: ~%.0f deg)',
  ['Wheel angle'] = 'Radwinkel',
  ['Up to 80 degrees (further, the tie rod would flip over). Above ~45 the wheels may rub the body or the arms; if the vehicle gets unstable, the change is undone by itself.'] = 'Bis 80 Grad (weiter würde die Spurstange umschlagen). Über ~45 können die Räder an Karosserie oder Lenkern schleifen; wird das Fahrzeug instabil, wird die Änderung von selbst rückgängig gemacht.',
  ['APPLY THE STEERING'] = 'LENKUNG ANWENDEN',
  ['The front wheels will turn up to ~%d deg.'] = 'Die Vorderräder schlagen bis ~%d deg ein.',
  ['The steering lock is factory again.'] = 'Der Lenkeinschlag ist wieder ab Werk.',
  ['The vehicle\'s steering cylinders hold the wheels straight, the virtual steering turns them.'] = 'Die Lenkzylinder des Fahrzeugs halten die Räder gerade, die virtuelle Lenkung dreht sie.',
  ['The front wheel hubs could not be separated - the vehicle keeps its own steering.'] = 'Die Naben der Vorderräder ließen sich nicht abtrennen - das Fahrzeug behält seine eigene Lenkung.',
  ['State: on - front wheels up to ~%d deg.'] = 'Status: an - Vorderräder bis ~%d deg.',
  ['Only what is inside the orange shape is cut out - the rest of the part stays.'] = 'Nur was in der orangen Form liegt, wird ausgeschnitten - der Rest des Teils bleibt.',
  ['Part: length %.2f m, width %.2f m, height %.2f m'] = 'Teil: Länge %.2f m, Breite %.2f m, Höhe %.2f m',
}
